2602	 * @brief 道路层：低等级先画、高等级后画；每级"壳→芯"成对。
2603	 *
2604	 * STYLE.md §3 最后一条：路口处高等级自然压住低等级，不需要额外的连接处理。
2605	 * 每级内部仍是"先本级的全部壳、再本级的全部芯"，同一等级的路口不会被同级的
2606	 * 壳切断。绑定索引时两遍 pass 只按 `rec[0]` 过滤；未绑定/索引溢出时退回逐
2607	 * class 全层扫描（像素结果一致）。
2608	 */
2609	static void draw_road_layer(vmap_canvas_t * c, const vmap_tile_t * tile,
2610	    uint16_t extent, float base_x, float base_y, float scale,
2611	    vmap_point_t * scratch, int scratch_cap)
2612	{
2613	    const float u = 256.0f * scale / (float)extent;
2614	    const int32_t ws_q8 = road_width_scale_q8(scale);
2615	    int cls;
2616	
2617	    if (s_road_refs && s_road_ref_cap > 0) {
2618	        /* 一次扫描：装本瓦片 ROAD 层的要素记录起点，同时记录 class 区间。*/
2619	        vmap_feature_iter_t scan = vmap_tile_layer_iter(tile, VMAP_LAYER_ROAD);
2620	        const uint8_t * layer_end = scan.end;
2621	        int n = 0;
2622	        int prev = 0;
2623	        bool overflow = false;
2624	        bool sorted = true;
2625	
2626	        for (cls = 0; cls < ROAD_STYLE_NUM; cls++) {
2627	            s_road_cls_start[cls] = 0;
2628	            s_road_cls_end[cls] = 0;
2629	        }
2630	
2631	        while (n < s_road_ref_cap) {
2632	            const uint8_t * rec = scan.ptr;
2633	            vmap_feature_t f;
2634	            int cls_now;
2635	
2636	            if (!vmap_feature_iter_next(&scan, &f)) {
2637	                break;
2638	            }
2639	            cls_now = road_norm_class(rec[0]);
2640	            if (n == 0) {
2641	                prev = cls_now;
2642	                s_road_cls_start[cls_now] = 0;
2643	            } else if (cls_now != prev) {
2644	                if (cls_now < prev) {
2645	                    sorted = false;
2646	                }
2647	                s_road_cls_end[prev] = (uint16_t)n;
2648	                s_road_cls_start[cls_now] = (uint16_t)n;
2649	                prev = cls_now;
2650	            }
2651	            s_road_refs[n++].rec = rec;
2652	        }
2653	        if (n == s_road_ref_cap && scan.remaining > 0) {
2654	            overflow = true;
2655	        }
2656	
2657	        if (!overflow) {
2658	            s_road_sorted = sorted && n > 0;
2659	            if (n > 0) {
2660	                s_road_cls_end[prev] = (uint16_t)n;
2661	            }
2662	
2663	            for (cls = VMAP_ROAD_PATH; cls >= VMAP_ROAD_MOTORWAY; cls--) {
2664	                if (!vmap_style_road_visible((uint8_t)cls, scale)) {
2665	                    continue;
2666	                }
2667	                /* 壳 → 芯 成对；path 的壳在 road_stroke_feature() 里直接跳过。 */
2668	                if (s_road_sorted) {
2669	                    const int start = s_road_cls_start[cls];
2670	                    const int end = s_road_cls_end[cls];
2671	
2672	                    if (start >= end) {
2673	                        continue;
2674	                    }
2675	                    road_stroke_refs_range(c, s_road_refs, start, end, layer_end,
2676	                        cls, true, base_x, base_y, u, ws_q8, scratch,
2677	                        scratch_cap);
2678	                    road_stroke_refs_range(c, s_road_refs, start, end, layer_end,
2679	                        cls, false, base_x, base_y, u, ws_q8, scratch,
2680	                        scratch_cap);
2681	                } else {
2682	                    /* 旧瓦片（未按 class 排序）：退回逐 class 全量过滤。 */
2683	                    road_stroke_refs(c, s_road_refs, n, layer_end, cls, true,
2684	                        base_x, base_y, u, ws_q8, scratch, scratch_cap);
2685	                    road_stroke_refs(c, s_road_refs, n, layer_end, cls, false,
2686	                        base_x, base_y, u, ws_q8, scratch, scratch_cap);
2687	                }
2688	            }
2689	            return;
2690	        }
2691	    }
2692	
2693	    /* 回退：未绑定索引、cap<=0 或索引溢出时走原实现（逐 class 全层扫描）。 */
2694	    for (cls = VMAP_ROAD_PATH; cls >= VMAP_ROAD_MOTORWAY; cls--) {
2695	        if (!vmap_style_road_visible((uint8_t)cls, scale)) {
2696	            continue;
2697	        }
2698	        road_stroke_scan(c, tile, cls, true, base_x, base_y, u, ws_q8, scratch,
2699	            scratch_cap);
2700	        road_stroke_scan(c, tile, cls, false, base_x, base_y, u, ws_q8, scratch,
2701	            scratch_cap);
2702	    }
2703	}
