2758	    if (!c || !c->buf) {
2759	        return;
2760	    }
2761	
2762	    if (dx == 0 && dy == 0) {
2763	        return;
2764	    }
2765	
2766	    if (dx >= c->w || dx <= -c->w || dy >= c->h || dy <= -c->h) {
2767	        vmap_render_clear(c, fill);
