CELL_LON=0.032899063849730509; CELL_LAT=0.026949335249730506
def tiles_of(path):
    raw=open(path,'rb').read()
    if raw[:4]!=b'VPKG': return None
    pay=raw[16:]
    if pay[:4]!=b'RIDX': return None
    ver,flags,rid=struct.unpack_from('<BBH',pay,4)
    n,goff,glen=struct.unpack_from('<III',pay,8)
    out=[]
    for i in range(n):
        z,_,x,y,_,off,size=struct.unpack_from('<BBHHHII',pay,52+i*16)
        out.append((x,y,pay[off:off+size]))
    return out
def parse_tile(data):
    if data[:4]!=b'VTIL': return None
    ext=struct.unpack_from('<H',data,6)[0] or 4096
    tx,ty=struct.unpack_from('<II',data,8); nlay=struct.unpack_from('<H',data,16)[0]
    p=20; layers={}
    for i in range(nlay):
        lid,_,fc,lb=struct.unpack_from('<BBHI',data,p); p+=8
        layers.setdefault(lid,[]).append((fc,data[p:p+lb])); p+=lb
    return dict(ext=ext,tx=tx,ty=ty,layers=layers)
def labels_of(data):
    t=parse_tile(data)
    if not t: return []
    res=[]
    for fc,d in t['layers'].get(4,[]):
        q=0
        for _ in range(fc):
            if q+8>len(d): break
            kind,pri,x,y,ln,pad=struct.unpack_from('<BBHHBB',d,q)
            txt=d[q+8:q+8+ln].decode('utf-8','replace')
            q+=8+ln
            res.append((kind,pri,x,y,txt,t))
    return res
