static void draw_road_polyline(vmap_canvas_t * c, const vmap_point_t * pts,
    int32_t n, int32_t width, uint16_t color)
{
    const int32_t join_r = (width + 1) / 2;
    int32_t i;

    if (!c || n < 2 || width < 1) {
        return;
    }

    /* 面状残渣（road_ring_is_area）由调用方统一跳过 —— 虚线和实线都要过那一关。 */

    /* 早退：点已经是画布坐标，包围盒几乎免费。 */
    {
