        int32_t by1 = pts[0].y;
        int32_t bx2 = pts[0].x;
        int32_t by2 = pts[0].y;

        for (i = 1; i < n; i++) {
            if (pts[i].x < bx1) { bx1 = pts[i].x; }
            if (pts[i].x > bx2) { bx2 = pts[i].x; }
            if (pts[i].y < by1) { by1 = pts[i].y; }
            if (pts[i].y > by2) { by2 = pts[i].y; }
