/** @brief 线宽倍率（Q8 定点，256 = 1.0），夹在 0.62 ~ 2.4。 */
static int32_t road_width_scale_q8(float scale)
{
    double ws;

    if (!(scale > 0.0f)) {
        return 256;
    }

    ws = sqrt((double)scale);
    if (ws < 0.62) {
        ws = 0.62;
    } else if (ws > 2.4) {
        ws = 2.4;
    }

    return (int32_t)lround(ws * 256.0);
}

